, sync_existing_names AS (
  UPDATE public.exercises e
  SET slug = m.slug
  FROM manifest_data m
  WHERE e.name = m.name AND (e.slug IS NULL OR e.slug <> m.slug)
    AND NOT EXISTS (SELECT 1 FROM public.exercises e2 WHERE e2.slug = m.slug AND e2.id <> e.id)
  RETURNING e.slug
)
INSERT INTO public.exercises (
  slug,
  name,
  muscle_group,
  category,
  equipment,
  instructions,
  difficulty,
  source_type
)
SELECT
  m.slug,
  m.name,
  m.muscle_group,
  m.category,
  m.equipment,
  m.instructions,
  m.difficulty,
  'yeti_v2'
FROM manifest_data m
WHERE NOT EXISTS (
  SELECT 1 FROM public.exercises e WHERE e.slug = m.slug
)
AND NOT EXISTS (
  SELECT 1 FROM public.exercises e WHERE e.name = m.name
)
ON CONFLICT (slug) DO NOTHING;
